-- M1-T3a: tenant isolation for the CRM setup tables, generated by tenantRlsSql (src/rls.ts).
-- No DELETE for app_user on pipelines / custom_field_defs / lead_sources: they are soft-deleted
-- (deleted_at / is_active). Stages can be deleted (after their leads are moved, M1-T3b).
ALTER TABLE "pipelines" ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
ALTER TABLE "pipelines" FORCE ROW LEVEL SECURITY;
--> statement-breakpoint
CREATE POLICY "tenant_isolation" ON "pipelines" AS PERMISSIVE FOR ALL TO PUBLIC USING ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid);
--> statement-breakpoint
REVOKE ALL ON "pipelines" FROM "app_user";
--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "pipelines" TO "app_user";
